#pragma once
/**
 * @file StationAnchors.hpp
 * @brief The station's anchor rows: GLONASS local-nuisance anchors, the test-only zero-ionosphere
 *        rows and the troposphere gradients' zero-mean prior.
 *
 * A family file of PASS B's station build: the steps of the family in
 * kStationBuildSteps / kStationCarrySteps (network/assembly/StationBuild.hpp), generated by
 * scripts/nom_pb1b_cut.py from the frozen text of networkPassB_'s produce loop.
 */

#include <cstdint>

namespace GnssProcessor {

// ---- PASS B station steps, declarations (generated by scripts/nom_pb1b_cut.py) ----

struct StationBuild;                       // network/assembly/StationBuild.hpp
struct StationCarryFrame;                  // network/assembly/StationBuild.hpp
enum class StationStep : std::uint8_t;     // network/assembly/StationBuild.hpp

/**
 * @brief GLONASS local-nuisance anchors (code-only network scope).
 *
 * Step `glonass_anchors` of kStationBuildSteps (network/assembly/StationBuild.hpp); its kinds:
 * GloIfbAnchor, GloIonoAnchor. It returns at once unless `config_.enableGlonassNetwork()`.
 * Records: the anchor rows. The frozen text of networkPassB_'s produce loop below its bindings
 *.
 * @param build One station's build: the station and its slot writable, the run read only.
 * @return StationStep::Next.
 */
StationStep networkGlonassAnchorRows(StationBuild& build);

/**
 * @brief Test-only zero-ionosphere rows (network.sim_zero_iono_sigma_m).
 *
 * Step `sim_zero_iono` of kStationBuildSteps (network/assembly/StationBuild.hpp); its kinds:
 * SimZeroIono. It returns at once unless `config_.getNetworkConfig().sim_zero_iono_sigma_m >
 * 0.0`. Records: the rows. The frozen text of networkPassB_'s produce loop below its bindings
 *.
 * @param build One station's build: the station and its slot writable, the run read only.
 * @return StationStep::Next.
 */
StationStep networkSimZeroIonoRows(StationBuild& build);

/**
 * @brief The troposphere gradients' zero-mean prior (network.tropo_gradient_prior_sigma_m).
 *
 * Step `tropo_gradient_prior` of kStationBuildSteps (network/assembly/StationBuild.hpp); its
 * kinds: TropoGradientPrior. One row per gradient column of the station's block, +1 on the
 * column, aimed at absolute zero (the target is minus the slot's linearization value), with
 * weight 1/sigma^2. The columns are uncarried and one epoch of data determines them to only
 * 5 to 7 mm, so without the rows they fit noise and take up station-level steps. It returns
 * at once unless the gradients are estimated (`knobs.tgrad_on`) and the sigma is positive;
 * a column left out of the local block this epoch gets no row.
 * @param build One station's build: the station and its slot writable, the run read only.
 * @return StationStep::Next.
 */
StationStep networkTropoGradientPriorRows(StationBuild& build);

// ---- End of the PASS B station steps, declarations ----

} // namespace GnssProcessor
